void PS2Runtime::Store128(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, __m128i value)
{
    alignas(16) uint64_t _parts[2];
    _mm_storeu_si128(reinterpret_cast<__m128i *>(_parts), value);
    ps2TraceGuestWrite(rdram, vaddr, 16u, _parts[0], _parts[1], "WRITE128", ctx);
    try
    {
        m_memory.write128(vaddr, value);
    }
    catch (const std::exception &)
    {
        SignalException(ctx, EXCEPTION_ADDRESS_ERROR_STORE);
    }
}

void PS2Runtime::kickGifDmaChainFromMMIO(uint8_t *rdram,
                                         R5900Context *ctx,
                                         uint32_t dPcrValue,
                                         uint32_t dStatValue,
                                         uint32_t tadr,
                                         uint32_t chcr)
{
    constexpr uint32_t D_PCR = 0x1000E020u;
    constexpr uint32_t D_STAT = 0x1000E010u;
    constexpr uint32_t GIF_TADR = 0x1000A030u;
    constexpr uint32_t GIF_CHCR = 0x1000A000u;

    ps2TraceGuestWrite(rdram, D_PCR, 4u, dPcrValue, 0u, "WRITE32", ctx);
    m_memory.writeIORegister(D_PCR, dPcrValue);
    ps2TraceGuestWrite(rdram, D_STAT, 4u, dStatValue, 0u, "WRITE32", ctx);
    m_memory.writeIORegister(D_STAT, dStatValue);
    ps2TraceGuestWrite(rdram, GIF_TADR, 4u, tadr, 0u, "WRITE32", ctx);
    m_memory.writeIORegister(GIF_TADR, tadr);
    ps2TraceGuestWrite(rdram, GIF_CHCR, 4u, chcr, 0u, "WRITE32", ctx);
    if (m_memory.tryProcessNativeGifImageUploadChain(m_gs, tadr, chcr))
    {
        drainCompletedDmacHandlers(rdram);
        return;
    }
    if (m_memory.tryProcessNativeGifPackedChain(m_gs, tadr, chcr))
    {
        drainCompletedDmacHandlers(rdram);
        return;
    }
    m_memory.writeIORegister(GIF_CHCR, chcr);
    m_memory.processPendingTransfers();
    drainCompletedDmacHandlers(rdram);
}

void PS2Runtime::requestStop()
{
    m_stopRequested.store(true, std::memory_order_relaxed);
    if (m_eeScheduler)
    {
        m_eeScheduler->requestStop();
    }
}

bool PS2Runtime::isStopRequested() const
{
    return m_stopRequested.load(std::memory_order_relaxed);
}

EeScheduler &PS2Runtime::eeScheduler()
{
    return *m_eeScheduler;
}

const EeScheduler &PS2Runtime::eeScheduler() const
{
    return *m_eeScheduler;
}

void PS2Runtime::postEeEvent(EeEvent event)
{
    m_eeScheduler->postEvent(event);
}

bool PS2Runtime::eeCheckpointDue(uint32_t cycles) noexcept
{
    // EXPERIMENT (session 27 part 7): PS2X_NO_MIDFUNC_PREEMPT=1 turns off the
    // scheduler's mid-function safe points (generated code calls this on branch
    // back-edges only).  Transfers between functions stay preemptible.  This is
    // the test for whether two logical chains are being interleaved on the main
    // thread's stack - the task pump's frame and FUN_00151300's frame are both
    // entered at sp=0x1ffff60, so an interleaving clobbers one saved `ra`.
    static const bool s_noMidFuncPreempt = std::getenv("PS2X_NO_MIDFUNC_PREEMPT") != nullptr;
    if (s_noMidFuncPreempt)
    {
        return false;
    }
    return m_eeScheduler->checkpointDue(cycles);
}

bool PS2Runtime::eeTransferPending() const noexcept
{
    return m_eeScheduler->transferPending();
}

void PS2Runtime::eeWaitVSyncTicks(uint32_t ticks, uint32_t resumePc)
{
    const uint64_t currentTick = m_eeScheduler->currentVSyncTick();
    const uint64_t waitTicks = std::max<uint64_t>(1u, ticks);
    m_eeScheduler->waitVSync(currentTick + waitTicks - 1u,
                             0,
                             [resumePc](R5900Context &context)
                             {
                                 context.pc = resumePc;
                             });
}

void PS2Runtime::addEeExitHandler(int threadId, uint32_t function, uint32_t argument)
{
    std::lock_guard lock(m_eeKernelStateMutex);
    m_eeExitHandlers[threadId].push_back({function, argument});
}

std::vector<PS2Runtime::EeExitHandlerRegistration> PS2Runtime::takeEeExitHandlers(int threadId)
{
    std::lock_guard lock(m_eeKernelStateMutex);
    auto it = m_eeExitHandlers.find(threadId);
    if (it == m_eeExitHandlers.end())
    {
        return {};
    }
    auto handlers = std::move(it->second);
    m_eeExitHandlers.erase(it);
    return handlers;
}

void PS2Runtime::removeEeExitHandlers(int threadId)
{
    std::lock_guard lock(m_eeKernelStateMutex);
    m_eeExitHandlers.erase(threadId);
}

bool PS2Runtime::findEeSyscallOverride(uint32_t syscallNumber, uint32_t &handler) const
{
    std::lock_guard lock(m_eeKernelStateMutex);
    const auto it = m_eeSyscallOverrides.find(syscallNumber);
    if (it == m_eeSyscallOverrides.end())
    {
        return false;
    }
    handler = it->second;
    return true;
}

void PS2Runtime::setEeSyscallOverride(uint8_t *rdram, uint32_t syscallNumber, uint32_t handler)
{
    constexpr uint32_t kTableBase = 0x80011F80u & 0x1FFFFFFFu;
    constexpr uint32_t kMirrorLimit = 0x00080000u;
    const int64_t offset = static_cast<int64_t>(static_cast<int32_t>(syscallNumber)) * 4;
    const int64_t address = static_cast<int64_t>(kTableBase) + offset;

    std::lock_guard lock(m_eeKernelStateMutex);
    if (handler == 0u)
    {
        m_eeSyscallOverrides.erase(syscallNumber);
    }
    else
    {
        m_eeSyscallOverrides[syscallNumber] = handler;
    }
    if (!rdram || address < 0 || address + 4 > kMirrorLimit)
    {
        return;
    }
    const uint32_t guestAddress = static_cast<uint32_t>(address);
    std::memcpy(rdram + guestAddress, &handler, sizeof(handler));
    if (handler == 0u)
    {
        m_eeSyscallMirrorAddresses.erase(guestAddress);
    }
    else
    {
        m_eeSyscallMirrorAddresses.insert(guestAddress);
    }
}

void PS2Runtime::initializeEeKernelState(uint8_t *rdram)
{
    if (!rdram)
    {
        return;
    }
    constexpr uint32_t kTableGuestBase = 0x80011F80u;
    constexpr uint32_t kTableBase = kTableGuestBase & 0x1FFFFFFFu;
    constexpr uint32_t kMirrorLimit = 0x00080000u;
    constexpr uint32_t kProbeBase = 0x000002F0u;

    std::lock_guard lock(m_eeKernelStateMutex);
    for (const uint32_t address : m_eeSyscallMirrorAddresses)
    {
        const uint32_t zero = 0u;
        std::memcpy(rdram + address, &zero, sizeof(zero));
    }
    m_eeSyscallMirrorAddresses.clear();
    const uint32_t high = kTableGuestBase >> 16;
    const uint32_t low = kTableGuestBase & 0xFFFFu;
    std::memcpy(rdram + kProbeBase, &high, sizeof(high));
    std::memcpy(rdram + kProbeBase + 8u, &low, sizeof(low));
    m_eeSyscallMirrorAddresses.insert(kProbeBase);
    m_eeSyscallMirrorAddresses.insert(kProbeBase + 8u);

    for (const auto &[syscallNumber, handler] : m_eeSyscallOverrides)
    {
        const int64_t offset = static_cast<int64_t>(static_cast<int32_t>(syscallNumber)) * 4;
        const int64_t address = static_cast<int64_t>(kTableBase) + offset;
        if (address < 0 || address + 4 > kMirrorLimit)
        {
            continue;
        }
        const uint32_t guestAddress = static_cast<uint32_t>(address);
        std::memcpy(rdram + guestAddress, &handler, sizeof(handler));
        m_eeSyscallMirrorAddresses.insert(guestAddress);
    }
}

void PS2Runtime::HandleIntegerOverflow(R5900Context *ctx)
{
    raiseCop0Exception(ctx, EXCEPTION_INTEGER_OVERFLOW);
}

void PS2Runtime::run()
{
    m_stopRequested.store(false, std::memory_order_relaxed);
    ps2_stubs::resetSifState();
    resetIop();
    ps2_stubs::resetAudioStubState();
    ps2_stubs::resetMpegStubState();
    initializeEeKernelState(m_memory.getRDRAM());
    m_cpuContext.r[4] = _mm_setzero_si128();
    m_cpuContext.r[5] = _mm_setzero_si128();
    m_cpuContext.r[29] = _mm_set_epi64x(0, static_cast<int64_t>(PS2_RAM_SIZE - 0x10u));
    m_debugPc.store(m_cpuContext.pc, std::memory_order_relaxed);
    m_debugRa.store(static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[31], 0)), std::memory_order_relaxed);
    m_debugSp.store(static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[29], 0)), std::memory_order_relaxed);
    m_debugGp.store(static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[28], 0)), std::memory_order_relaxed);

    RUNTIME_LOG("Starting execution at address 0x" << std::hex << m_cpuContext.pc << std::dec);

    // A blank image to use as a framebuffer
    Image blank = GenImageColor(FB_WIDTH, FB_HEIGHT, BLANK);
    Texture2D frameTex = LoadTextureFromImage(blank);
    UnloadImage(blank);

    std::atomic<bool> gameThreadFinished{false};

    std::thread gameThread([&]()
                           {
        ThreadNaming::SetCurrentThreadName("GameThread");
        try
        {
            m_eeScheduler->reset(m_memory.getRDRAM(), m_cpuContext);
            m_eeScheduler->run();
            if (m_vu) m_vu->reportFailure();
            const auto &iopFault = m_iopSubsystem->fault();
            if (iopFault.active)
                std::cerr << "IOP execution failed at PC=0x" << std::hex << iopFault.pc << std::dec << ": " << iopFault.reason.data() << '\n';
            uint32_t pc = m_debugPc.load(std::memory_order_relaxed);
            RUNTIME_LOG("Game thread returned. PC=0x" << std::hex << pc
                      << " RA=0x" << static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[31], 0)) << std::dec << std::endl);
        }
        catch (const std::exception &e)
        {
            std::cerr << "Error during program execution: " << e.what() << std::endl;
        }
        catch (...)
        {
            std::cerr << "Error during program execution: unknown exception" << std::endl;
        }
        gameThreadFinished.store(true, std::memory_order_release); });

    uint64_t tick = 0;
    std::exception_ptr presentationError;
    try
    {
        while (!isStopRequested() && !gameThreadFinished.load(std::memory_order_acquire))
        {
            PS2_IF_AGRESSIVE_LOGS({
                tick++;
                if ((tick % 120) == 0)
                {
                    uint64_t curDma = m_memory.dmaStartCount();
                    uint64_t curGif = m_memory.gifCopyCount();
                    uint64_t curGs = m_memory.gsWriteCount();
                    uint64_t curVif = m_memory.vifWriteCount();
                    const GSRegisters &gs = m_memory.gs();
                    const uint32_t dbgPc = m_debugPc.load(std::memory_order_relaxed);
                    const uint32_t dbgRa = m_debugRa.load(std::memory_order_relaxed);
                    const uint32_t dbgSp = m_debugSp.load(std::memory_order_relaxed);
                    const uint32_t dbgGp = m_debugGp.load(std::memory_order_relaxed);
                    const auto eeSnapshot = m_eeScheduler->snapshot();

                    RUNTIME_LOG("[run:tick] tick=" << tick
                                                   << " pc=0x" << std::hex << dbgPc
                                                   << " ra=0x" << dbgRa
                                                   << " sp=0x" << dbgSp
                                                   << " gp=0x" << dbgGp
                                                   << " dispfb1=0x" << gs.dispfb1
                                                   << " display1=0x" << gs.display1
                                                   << std::dec
                                                   << " activeThreads=" << eeSnapshot.threads.size()
                                                   << " dma=" << curDma
                                                   << " gif=" << curGif
                                                   << " gsw=" << curGs
                                                   << " vif=" << curVif
                                                   << std::endl);
                }
            });
            // TEMP DIAGNOSTIC: high-rate ADXF / stream-state sampler.  Prints only
            // when the observed state changes, so the allocate/free sequence and the
            // failure point are visible without flooding the log.
            {
                static auto s_next = std::chrono::steady_clock::now();
                static std::string s_last;
                static uint32_t s_prints = 0u;
                const auto now = std::chrono::steady_clock::now();
                if (s_prints < 80u && now >= s_next)
                {
                    s_next = now + std::chrono::milliseconds(100);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peek = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        auto ascii = [ram](uint32_t addr, uint32_t len) -> std::string {
                            std::string out;
                            for (uint32_t i = 0u; i < len; ++i)
                            {
                                const char c = static_cast<char>(ram[addr + i]);
                                out.push_back((c >= 0x20 && c < 0x7F) ? c : '.');
                            }
                            return out;
                        };

                        std::ostringstream os;
                        os << "a8=0x" << std::hex << peek(0x003910A8u)
                           << " ac=" << std::dec << static_cast<int32_t>(peek(0x003910ACu))
                           << " b0=0x" << std::hex << peek(0x003910B0u)
                           << " b4=" << std::dec << peek(0x003910B4u)
                           << " adxf=";
                        for (uint32_t i = 0u; i < 16u; ++i)
                        {
                            os << (ram[0x00390738u + i * 0x44u] ? '1' : '0');
                        }
                        os << " sj=";
                        for (uint32_t i = 0u; i < 40u; ++i)
                        {
                            os << (ram[0x0039E848u + i * 0x60u] ? '1' : '0');
                        }
                        os << " paths=";
                        for (uint32_t i = 0u; i < 40u; ++i)
                        {
                            const uint32_t base = 0x0039E848u + i * 0x60u;
                            const uint32_t p = peek(base + 0x50u);
                            if (p != 0u && p < 0x02000000u)
                            {
                                os << i << ":\"" << ascii(p, 0x30u) << "\" ";
                            }
                        }
                        os << "cvfs=\"" << ascii(0x003A55C8u, 0x40u) << "\""
                           << " msg=\"" << ascii(0x00390630u, 0x60u) << "\"";
                        // CRI VFS device table: 0x20 entries of 0x10 at 0x499F00,
                        // +0x00 object pointer, +0x04 inline 12-byte device name.
                        os << " devs=";
                        uint32_t devCount = 0u;
                        for (uint32_t i = 0u; i < 0x20u; ++i)
                        {
                            const uint32_t objPtr = peek(0x00499F00u + i * 0x10u);
                            if (objPtr == 0u)
                            {
                                continue;
                            }
                            ++devCount;
                            os << "\"" << ascii(0x00499F04u + i * 0x10u, 0x0Cu) << "\"@0x"
                               << std::hex << objPtr
                               << "/open=0x"
                               << (objPtr < 0x02000000u ? peek(objPtr + 0x10u) : 0u)
                               << std::dec << " ";
                        }
                        os << " (" << devCount << ")";
                        // Raw CDV vtable words, to compare against the ELF image.
                        os << " cdvv=";
                        for (uint32_t w = 0u; w < 8u; ++w)
                        {
                            os << std::hex << peek(0x003A6A98u + w * 4u) << ",";
                        }
                        os << std::dec;

                        const std::string state = os.str();
                        if (state != s_last)
                        {
                            s_last = state;
                            ++s_prints;
                            std::cerr << "[EE-seq] " << state << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): the boot task FUN_001660a0 waits for a
            // request object's status byte (table entry +2) to fall from 2 to 0 and
            // never sees it.  The table is 64 * 0x2c entries at 0x4A72C0 (built by
            // FUN_001f8be0), linked into a priority list whose head/tail/count live
            // gp-relative at gp-0x7860 / gp-0x785c / gp-0x7850.  Dump the queue and
            // the live entries so the pending request is identifiable.
            {
                static auto s_reqNext = std::chrono::steady_clock::now();
                static std::string s_reqLast;
                static uint32_t s_reqPrints = 0u;
                const auto reqNow = std::chrono::steady_clock::now();
                if (s_reqPrints < 200u && reqNow >= s_reqNext)
                {
                    s_reqNext = reqNow + std::chrono::milliseconds(300);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peekReq = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        const uint32_t gp = m_debugGp.load(std::memory_order_relaxed);
                        const uint32_t head = gp != 0u ? peekReq(gp - 0x7860u) : 0u;
                        const uint32_t tail = gp != 0u ? peekReq(gp - 0x785cu) : 0u;
                        const uint32_t count = gp != 0u ? peekReq(gp - 0x7850u) : 0u;

                        std::ostringstream ros;
                        ros << std::hex << "gp=0x" << gp << " head=0x" << head << " tail=0x" << tail
                            << std::dec << " count=" << count << " entries:";
                        for (uint32_t i = 0u; i < 8u; ++i)
                        {
                            const uint32_t base = 0x004A72C0u + i * 0x2cu;
                            const uint32_t w0 = peekReq(base + 0x00u);
                            const uint32_t id = peekReq(base + 0x08u);
                            const uint32_t prev = peekReq(base + 0x24u);
                            const uint32_t next = peekReq(base + 0x28u);
                            if (((w0 >> 24) & 0xFFu) == 0u && id == 0u && prev == 0u && next == 0u)
                            {
                                continue;
                            }
                            float f28 = 0.0f;
                            const uint32_t w1c = peekReq(base + 0x1cu);
                            std::memcpy(&f28, &w1c, sizeof(f28));
                            ros << " [" << i << "] b0=" << ((w0 >> 0) & 0xFFu)
                                << " b1=" << ((w0 >> 8) & 0xFFu)
                                << " b2=" << ((w0 >> 16) & 0xFFu)
                                << " b3=" << ((w0 >> 24) & 0xFFu)
                                << " +4=0x" << std::hex << peekReq(base + 0x04u)
                                << " id=0x" << id
                                << " +10=0x" << peekReq(base + 0x10u)
                                << " +14=0x" << peekReq(base + 0x14u)
                                << " +18=0x" << peekReq(base + 0x18u)
                                << " +1c=0x" << std::hex << w1c << std::dec << " f=" << f28
                                << " +20=0x" << peekReq(base + 0x20u)
                                << " prev=0x" << prev << " next=0x" << next << std::dec << "]";
                        }

                        const std::string reqState = ros.str();
                        if (reqState != s_reqLast)
                        {
                            s_reqLast = reqState;
                            ++s_reqPrints;
                            std::cerr << "[EE-req] " << reqState << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): the ADXF stream-job array at 0x39E848
            // (40 slots * 0x60).  Slot 16 goes active for CDV:\AFS\SYS_REG.AFS and
            // never retires, and no CDVD stream read is ever issued for it.  Dump
            // every active slot in full so the stall point is visible.
            {
                static auto s_jobNext = std::chrono::steady_clock::now();
                static std::string s_jobLast;
                static uint32_t s_jobPrints = 0u;
                const auto jobNow = std::chrono::steady_clock::now();
                if (s_jobPrints < 40u && jobNow >= s_jobNext)
                {
                    s_jobNext = jobNow + std::chrono::milliseconds(500);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peekJob = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        std::ostringstream jos;
                        bool any = false;
                        for (uint32_t i = 0u; i < 40u; ++i)
                        {
                            const uint32_t base = 0x0039E848u + i * 0x60u;
                            if (ram[base] == 0u)
                            {
                                continue;
                            }
                            any = true;
                            jos << " job[" << i << "]=";
                            for (uint32_t w = 0u; w < 0x60u; w += 4u)
                            {
                                jos << std::hex << peekJob(base + w) << " ";
                            }
                            jos << std::dec;
                        }
                        if (!any)
                        {
                            jos << "(none active)";
                        }
                        const std::string jobState = jos.str();
                        if (jobState != s_jobLast)
                        {
                            s_jobLast = jobState;
                            ++s_jobPrints;
                            std::cerr << "[EE-job] " << jobState << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): the CDV VFS device keeps its own 40-slot
            // request array at 0x3A6B00 (stride 0x48, object header at 0x3A6A90).
            // FUN_001ad2e8 only pumps a slot when header word 0x3A6A90 is set and the
            // slot's first byte is 1, and FUN_001ad220 then polls the request handle
            // at slot+0x1c.  Dump the header, every live slot and the ADXF file object
            // (0x499DC0) to see whether job 16 ever reaches the device at all.
            {
                static auto s_cdvNext = std::chrono::steady_clock::now();
                static std::string s_cdvLast;
                static uint32_t s_cdvPrints = 0u;
                const auto cdvNow = std::chrono::steady_clock::now();
                if (s_cdvPrints < 40u && cdvNow >= s_cdvNext)
                {
                    s_cdvNext = cdvNow + std::chrono::milliseconds(500);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peekCdv = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        std::ostringstream cos;
                        cos << std::hex << "hdr=";
                        for (uint32_t w = 0x3A6A90u; w < 0x3A6A90u + 0x10u; w += 4u)
                        {
                            cos << peekCdv(w) << " ";
                        }
                        for (uint32_t i = 0u; i < 40u; ++i)
                        {
                            const uint32_t base = 0x003A6B00u + i * 0x48u;
                            const uint32_t h = peekCdv(base + 0x1cu);
                            if (ram[base] == 0u && h == 0u)
                            {
                                continue;
                            }
                            cos << " slot[" << std::dec << i << "]=";
                            for (uint32_t w = 0u; w < 0x48u; w += 4u)
                            {
                                cos << std::hex << peekCdv(base + w) << " ";
                            }
                            cos << std::dec;
                        }
                        cos << " fileobj=";
                        for (uint32_t w = 0u; w < 0x40u; w += 4u)
                        {
                            cos << std::hex << peekCdv(0x00499DC0u + w) << " ";
                        }
                        const std::string cdvState = cos.str();
                        if (cdvState != s_cdvLast)
                        {
                            s_cdvLast = cdvState;
                            ++s_cdvPrints;
                            std::cerr << "[EE-cdv] " << cdvState << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): the CRI ADXF handle pool - 16 slots of
            // 0x44 at 0x390738 (FUN_00196870).  Byte +1 is the state the request
            // handler spins on (1 idle -> 2 read started -> 3 complete); +4 is the
            // stm handle, +8 the stream job, +0xc size, +0x14 position, +0x1c
            // length, +0x24 buffer, +0x30 base offset.  Dump every live handle and
            // the head of its stm handle / stream job so the stalled read is visible.
            {
                static auto s_adxfNext = std::chrono::steady_clock::now();
                static std::string s_adxfLast;
                static uint32_t s_adxfPrints = 0u;
                const auto adxfNow = std::chrono::steady_clock::now();
                if (s_adxfPrints < 80u && adxfNow >= s_adxfNext)
                {
                    s_adxfNext = adxfNow + std::chrono::milliseconds(1000);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peekAdxf = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        std::ostringstream aos;
                        for (uint32_t i = 0u; i < 16u; ++i)
                        {
                            const uint32_t base = 0x00390738u + i * 0x44u;
                            if (ram[base] == 0u)
                            {
                                continue;
                            }
                            aos << " adxf[" << i << "] st=" << ((int)ram[base + 1u] & 0xFF)
                                << " b2=" << ((int)ram[base + 2u] & 0xFF)
                                << " b3=" << ((int)ram[base + 3u] & 0xFF) << " " << std::hex;
                            for (uint32_t w = 4u; w < 0x44u; w += 4u)
                            {
                                aos << peekAdxf(base + w) << " ";
                            }
                            const uint32_t stm = peekAdxf(base + 4u);
                            const uint32_t sjh = peekAdxf(base + 8u);
                            if (stm != 0u && stm < PS2_RAM_SIZE)
                            {
                                aos << "| stm=";
                                for (uint32_t w = 0u; w < 0x60u; w += 4u)
                                {
                                    aos << peekAdxf(stm + w) << " ";
                                }
                            }
                            if (sjh != 0u && sjh < PS2_RAM_SIZE)
                            {
                                aos << "| sj=";
                                for (uint32_t w = 0u; w < 0x30u; w += 4u)
                                {
                                    aos << peekAdxf(sjh + w) << " ";
                                }
                            }
                            aos << std::dec << "\n";
                        }
                        const std::string adxfState = aos.str();
                        if (adxfState != s_adxfLast)
                        {
                            s_adxfLast = adxfState;
                            ++s_adxfPrints;
                            std::cerr << "[EE-adxf]\n" << adxfState << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): the game's cooperative task pool - 64
            // slots of 0x210 at 0x407160 (FUN_00151c80).  Byte +0x1f0 is the task
            // state (1 runnable, 3 retiring), +0x1f1 the group the pump matches,
            // +0x1b0 the entry function, +0x1b4 the resume target the scheduler
            // jumps back through after a yield (FUN_00152200).  Enumerating every
            // live task with its entry and resume target shows which tasks exist
            // and where each one is parked - the CRI server pump (FUN_00197940)
            // has no call sites, so a task has to be driving it.
            {
                static auto s_taskNext = std::chrono::steady_clock::now();
                static std::string s_taskLast;
                static uint32_t s_taskPrints = 0u;
                const auto taskNow = std::chrono::steady_clock::now();
                if (s_taskPrints < 80u && taskNow >= s_taskNext)
                {
                    s_taskNext = taskNow + std::chrono::milliseconds(1000);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peekTask = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        std::ostringstream tos;
                        tos << std::hex << "head=" << peekTask(0x003DA194u) << "\n";
                        for (uint32_t i = 0u; i < 64u; ++i)
                        {
                            const uint32_t base = 0x00407160u + i * 0x210u;
                            const uint32_t state = ram[base + 0x1f0u];
                            if (state == 0u)
                            {
                                continue;
                            }
                            tos << "  t[" << std::dec << i << "] st=" << (state & 0xFF)
                                << " g=" << (ram[base + 0x1f1u] & 0xFF)
                                << " f2=" << (ram[base + 0x1f2u] & 0xFF)
                                << " f3=" << (ram[base + 0x1f3u] & 0xFF)
                                << std::hex
                                << " entry=" << peekTask(base + 0x1b0u)
                                << " rsm=" << peekTask(base + 0x1b4u)
                                << " ra=" << peekTask(base + 0x1a8u)
                                << " ac=" << peekTask(base + 0x1acu)
                                << " ctx=" << peekTask(base + 0x204u)
                                << " cp=" << peekTask(base + 0x208u)
                                << " stk=" << peekTask(base + 0x20cu)
                                << " next=" << peekTask(base + 0x1fcu)
                                << "\n";
                        }
                        const std::string taskState = tos.str();
                        if (taskState != s_taskLast)
                        {
                            s_taskLast = taskState;
                            ++s_taskPrints;
                            std::cerr << "[EE-tasks]\n" << taskState << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): the CRI service-group registry that
            // CriAdxt_Init registers the server pump into.  Registry = 8 groups at
            // 0x49C6A0, stride 0x30, six {fnptr,arg} pairs each; the pump sits at
            // group 4 slot 0.  FUN_001b7688 bumps a per-group call counter at
            // 0x3B7330 and sets an in-progress flag at 0x3B7350.  Dumping both
            // shows directly whether the game ever services group 4.
            {
                static auto s_srvNext = std::chrono::steady_clock::now();
                static std::string s_srvLast;
                static uint32_t s_srvPrints = 0u;
                const auto srvNow = std::chrono::steady_clock::now();
                if (s_srvPrints < 80u && srvNow >= s_srvNext)
                {
                    s_srvNext = srvNow + std::chrono::milliseconds(1000);
                    if (const uint8_t *ram = m_eeScheduler->rdram())
                    {
                        auto peekSrv = [ram](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, ram + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };
                        std::ostringstream sos;
                        sos << std::hex;
                        for (uint32_t k = 0u; k < 8u; ++k)
                        {
                            const uint32_t base = 0x0049C6A0u + k * 0x30u;
                            sos << "g" << std::dec << k << ":";
                            for (uint32_t e = 0u; e < 6u; ++e)
                            {
                                const uint32_t fn = peekSrv(base + e * 8u);
                                if (fn == 0u)
                                {
                                    continue;
                                }
                                sos << " " << std::hex << fn << "/" << peekSrv(base + e * 8u + 4u);
                            }
                            sos << (k + 1u < 8u ? " | " : "\n");
                        }
                        sos << "svc:";
                        for (uint32_t k = 0u; k < 8u; ++k)
                        {
                            sos << " " << std::dec << peekSrv(0x003B7330u + k * 4u);
                        }
                        sos << " busy:";
                        for (uint32_t k = 0u; k < 8u; ++k)
                        {
                            sos << " " << std::dec << peekSrv(0x003B7350u + k * 4u);
                        }
                        // CRI ADXT init-gate state: DAT_003942c4 is the CriSrv
                        // registration count that FUN_00199780() tests, DAT_00393228
                        // gates CriAdxt_Init, and 0x393230/0x393238 hold the group-5
                        // and group-4 registration handles it returns.
                        sos << "\ncri: c42c4=" << std::dec << peekSrv(0x003942C4u)
                            << " c3228=" << peekSrv(0x00393228u)
                            << " c3230=0x" << std::hex << peekSrv(0x00393230u)
                            << " c3238=0x" << std::hex << peekSrv(0x00393238u)
                            << " c323c=" << std::dec << peekSrv(0x0039323Cu)
                            << " c43dc=" << peekSrv(0x003943DCu)
                            << " c4350=" << peekSrv(0x00394350u)
                            << " tid:5c/60/64=" << peekSrv(0x0039435Cu) << ","
                            << peekSrv(0x00394360u) << "," << peekSrv(0x00394364u)
                            << " c4368=" << peekSrv(0x00394368u);
                        // ADXF partition state.  ADXF_GetPtStat(ptid) returns -3
                        // ("E0041303:illigal parameter 'ptid'") whenever ptid !=
                        // DAT_003910AC, so 0x3910AC is the single word that decides
                        // whether the 6-job AFS loader can ever see state 3.
                        // 0x3910A8 is the ADXF file handle, 0x3910A4 the flags,
                        // 0x3910B0/0x3910B4 the current load buffer/length.
                        // Initial value is -1 ("no partition"); it is only ever
                        // set inside `if (DAT_003910AC < 0)` in FUN_001961a8 and is
                        // reset by the close paths, so a -1 here means the loader
                        // is querying a partition nothing has opened.
                        sos << "\nadxf: ac=" << std::dec
                            << static_cast<int32_t>(peekSrv(0x003910ACu))
                            << " a8=0x" << std::hex << peekSrv(0x003910A8u)
                            << " a4=" << std::dec
                            << static_cast<int32_t>(peekSrv(0x003910A4u))
                            << " b0=0x" << std::hex << peekSrv(0x003910B0u)
                            << " b4=" << std::dec << peekSrv(0x003910B4u)
                            << " msg=\"";
                        for (uint32_t c = 0u; c < 0x60u; ++c)
                        {
                            const char ch = static_cast<char>(ram[(0x00390630u + c) & PS2_RAM_MASK]);
                            if (ch == '\0')
                            {
                                break;
                            }
                            sos << (ch >= 0x20 && ch < 0x7F ? ch : '.');
                        }
                        sos << "\"";
                        const std::string srvState = sos.str();
                        if (srvState != s_srvLast)
                        {
                            s_srvLast = srvState;
                            ++s_srvPrints;
                            std::cerr << "[EE-srv] " << srvState << std::endl;
                        }
                    }
                }
            }

            // TEMP DIAGNOSTIC (session 20): uncapped entry-hit counts for every
            // labelled guest address, printed whenever the totals move.  WATCH-ENTRY
            // caps at three lines per address, which hides whether a path keeps
            // running (the CDV device read path for the stalled ADXF job).
            {
                static auto s_hitsNext = std::chrono::steady_clock::now();
                static std::string s_hitsLast;
                const auto hitsNow = std::chrono::steady_clock::now();
                if (hitsNow >= s_hitsNext)
                {
                    s_hitsNext = hitsNow + std::chrono::milliseconds(2000);
                    std::ostringstream hos;
                    bool first = true;
                    {
                        std::lock_guard<std::mutex> hitLock(g_watchHitsMutex);
                        for (const auto &[addr, hits] : g_watchHits)
                        {
                            hos << (first ? "" : " ") << "0x" << std::hex << addr
                                << std::dec << "=" << hits;
                            first = false;
                        }
                    }
                    const std::string hitsState = hos.str();
                    if (!hitsState.empty() && hitsState != s_hitsLast)
                    {
                        s_hitsLast = hitsState;
                        std::cerr << "[EE-hits] " << hitsState << std::endl;
                    }
                }
            }

            // TEMP DIAGNOSTIC (boot-stall triage): when the EE scheduler thread
            // gets stuck inside a single recompiled invocation the scheduler-side
            // heartbeats stop entirely, because the loop never comes back around.
            // Sample the *live* guest instruction pointer from this host thread
            // while that lasts so the spinning code shows up in the log.
            {
                static uint32_t s_watchdogDbgPc = 0xFFFFFFFFu;
                static auto s_watchdogSince = std::chrono::steady_clock::now();
                static int s_watchdogReports = 0;
                const uint32_t watchdogDbgPc = m_debugPc.load(std::memory_order_relaxed);
                const auto watchdogNow = std::chrono::steady_clock::now();
                if (watchdogDbgPc != s_watchdogDbgPc)
                {
                    s_watchdogDbgPc = watchdogDbgPc;
                    s_watchdogSince = watchdogNow;
                    s_watchdogReports = 0;
                }
                else if (s_watchdogReports < 8 &&
                         std::chrono::duration_cast<std::chrono::seconds>(watchdogNow - s_watchdogSince).count() >= 3)
                {
                    ++s_watchdogReports;
                    const R5900Context *watchdogLive = m_eeScheduler->currentContext();
                    std::cerr << "[EE-wd] report=" << s_watchdogReports
                              << " executing=" << (m_eeScheduler->isExecutingGuest() ? 1 : 0)
                              << " tid=" << m_eeScheduler->currentThreadId()
                              << " diagStage=" << s_diagStage
                              << " diagCalls=" << s_diagCalls
                              << " dbgPc=0x" << std::hex << watchdogDbgPc;
                    if (watchdogLive != nullptr)
                    {
                        std::cerr << " livePc=0x" << watchdogLive->pc
                                  << " ra=0x" << static_cast<uint32_t>(_mm_extract_epi32(watchdogLive->r[31], 0))
                                  << " sp=0x" << static_cast<uint32_t>(_mm_extract_epi32(watchdogLive->r[29], 0))
                                  << " a0=0x" << static_cast<uint32_t>(_mm_extract_epi32(watchdogLive->r[4], 0))
                                  << " v0=0x" << static_cast<uint32_t>(_mm_extract_epi32(watchdogLive->r[2], 0));
                    }
                    std::cerr << std::dec << std::endl;

                    // TEMP DIAGNOSTIC: capture the full guest state once the
                    // stall is confirmed, so the waiting thread, the ADXF handle
                    // and the RPC client can be inspected without another run.
                    if (s_watchdogReports == 1 || s_watchdogReports == 4)
                    {
                        const auto snap = m_eeScheduler->snapshot();
                        for (const auto &thread : snap.threads)
                        {
                            std::cerr << "[EE-wd:thread] id=" << thread.id
                                      << " status=" << static_cast<int>(thread.status)
                                      << " prio=" << thread.currentPriority
                                      << " wait=" << static_cast<int>(thread.waitReason)
                                      << " waitId=" << thread.waitId
                                      << " pc=0x" << std::hex << thread.pc
                                      << " ra=0x" << thread.ra
                                      << " sp=0x" << thread.sp
                                      << " entry=0x" << thread.entry
                                      << std::dec << std::endl;
                        }
                        for (const auto &sem : snap.semaphores)
                        {
                            std::cerr << "[EE-wd:sem] id=" << sem.id
                                      << " count=" << sem.count
                                      << " max=" << sem.maxCount
                                      << " waiters=" << sem.waiters << std::endl;
                        }

                        uint8_t *wdRam = m_memory.getRDRAM();
                        auto wdPeek = [wdRam](uint32_t addr) -> uint32_t {
                            uint32_t value = 0u;
                            std::memcpy(&value, wdRam + ((addr & PS2_RAM_MASK) & ~3u), sizeof(value));
                            return value;
                        };

                        const uint32_t adxfHandle = wdPeek(0x003910A8u);
                        std::cerr << "[EE-wd:adxf] handle=0x" << std::hex << adxfHandle << " words:";
                        for (uint32_t i = 0u; i < 12u; ++i)
                        {
                            std::cerr << " " << wdPeek(adxfHandle + i * 4u);
                        }
                        std::cerr << std::dec << std::endl;

                        // TEMP DIAGNOSTIC: the ADXF library formats status/error
                        // messages into this buffer (0x390630) and hands them to the
                        // callback registered at 0x390628.
                        std::cerr << "[EE-wd:adxfmsg] ";
                        for (uint32_t i = 0u; i < 0x40u; ++i)
                        {
                            const char c = static_cast<char>(wdRam[(0x00390630u + i) & PS2_RAM_MASK]);
                            std::cerr << ((c >= 0x20 && c < 0x7F) ? c : '.');
                        }
                        std::cerr << std::endl;

                        // TEMP DIAGNOSTIC: ADXF loader globals.  DAT_003910a8 is the
                        // open handle, 0x3910ac the partition currently loading,
                        // 0x3910b0 the tmpbuf handed to the async read and 0x3910b4
                        // the sector count; FUN_001970e8 rejects a tmpbuf that is not
                        // 64-byte aligned (and leaves 0x3910ac set, wedging the loop).
                        std::cerr << "[EE-wd:adxfglob] a4=" << wdPeek(0x003910A4u)
                                  << " a8=0x" << std::hex << wdPeek(0x003910A8u)
                                  << " ac=" << std::dec << static_cast<int32_t>(wdPeek(0x003910ACu))
                                  << " b0=0x" << std::hex << wdPeek(0x003910B0u)
                                  << " b0mod64=" << std::dec << (wdPeek(0x003910B0u) & 0x3Fu)
                                  << " b4=" << wdPeek(0x003910B4u)
                                  << " part0=0x" << std::hex << wdPeek(0x00390B78u)
                                  << " cb5slot0=0x" << wdPeek(0x0049C790u)
                                  << " ch4=" << std::dec << wdPeek(0x003B7340u)
                                  << " ch5=" << wdPeek(0x003B7344u)
                                  << std::dec << std::endl;

                        std::cerr << "[EE-wd:client] words:";
                        for (uint32_t i = 0u; i < 12u; ++i)
                        {
                            std::cerr << " " << std::hex << wdPeek(0x003DBA80u + i * 4u);
                        }
                        std::cerr << std::dec << std::endl;

                        // TEMP DIAGNOSTIC: libcdvd stream client (0x3863D0) and
                        // the request state the end handler is expected to clear.
                        std::cerr << "[EE-wd:sclient] words:";
                        for (uint32_t i = 0u; i < 12u; ++i)
                        {
                            std::cerr << " " << std::hex << wdPeek(0x003863D0u + i * 4u);
                        }
                        std::cerr << std::dec << std::endl;
                        std::cerr << "[EE-wd:stream] busy=" << std::hex << wdPeek(0x00385234u)
                                  << " state=" << wdPeek(0x00385260u)
                                  << " sema=0x" << wdPeek(0x00385228u)
                                  << " done=0x" << wdPeek(0x003863C0u)
                                  << " resp:";
                        for (uint32_t i = 0u; i < 8u; ++i)
                        {
                            std::cerr << " " << wdPeek(0x00386300u + i * 4u);
                        }
                        std::cerr << " dest:";
                        for (uint32_t i = 0u; i < 4u; ++i)
                        {
                            std::cerr << " " << wdPeek(0x0049A440u + i * 4u);
                        }
                        std::cerr << std::dec << std::endl;

                        // TEMP DIAGNOSTIC: CRI stream-engine slots polled by the
                        // ADXF server callback (FUN_001b0d00, 32 slots of 0x238).
                        for (uint32_t slot = 0u; slot < 32u; ++slot)
                        {
                            const uint32_t base = 0x003A7FB0u + slot * 0x238u;
                            const uint32_t head = wdPeek(base);
                            if (head == 0u && wdPeek(base + 4u) == 0u)
                            {
                                continue;
                            }
                            std::cerr << "[EE-wd:sj] slot=" << std::dec << slot
                                      << " b0=0x" << std::hex << (head & 0xFFu)
                                      << " b1=0x" << ((head >> 8) & 0xFFu)
                                      << " b2=0x" << ((head >> 16) & 0xFFu)
                                      << " b3=0x" << ((head >> 24) & 0xFFu)
                                      << " w1=0x" << wdPeek(base + 4u)
                                      << " w20=0x" << wdPeek(base + 0x20u)
                                      << " w24=0x" << wdPeek(base + 0x24u)
                                      << " w28=0x" << wdPeek(base + 0x28u)
                                      << std::dec << std::endl;
                        }

                        const uint32_t partTable = wdPeek(0x003DB368u);
                        std::cerr << "[EE-wd:table] ptr=0x" << std::hex << partTable << std::dec
                                  << std::endl;
                        for (uint32_t i = 0u; i < 6u && partTable != 0u; ++i)
                        {
                            const uint32_t entry = partTable + i * 0x28u;
                            std::cerr << "[EE-wd:part] i=" << std::dec << i
                                      << " blocks=0x" << std::hex << wdPeek(entry + 0x20u)
                                      << " handle=0x" << wdPeek(entry + 0x24u)
                                      << " name0=0x" << wdPeek(entry)
                                      << std::dec << std::endl;
                        }
                    }
                }
            }

            uint32_t presentWidth = FB_WIDTH;
            uint32_t presentHeight = DEFAULT_DISPLAY_HEIGHT;
            UploadFrame(frameTex, this, presentWidth, presentHeight);

            Texture2D presentationTexture = frameTex;
            float aspectRatio = 0.0f;
#ifdef PS2X_GS_PARALLEL
            auto gpuFrame = m_gs.getLatchedGpuFrame(presentWidth, presentHeight, aspectRatio);
            presentationTexture = {};
            if (gpuFrame)
                presentationTexture = Texture2D{gpuFrame->AcquireTexture(), int(presentWidth), int(presentHeight), 1, PIXELFORMAT_UNCOMPRESSED_R8G8B8A8};
#endif

            BeginDrawing();
            ClearBackground(BLACK);
            const float srcWidth = static_cast<float>(std::max<uint32_t>(1u, presentWidth));
            const float srcHeight = static_cast<float>(std::max<uint32_t>(1u, presentHeight));
            const float screenWidth = static_cast<float>(GetScreenWidth());
            const float screenHeight = static_cast<float>(GetScreenHeight());
            const float displayWidth = aspectRatio > 0 ? srcHeight * aspectRatio : srcWidth;
            const float scale = std::min(screenWidth / displayWidth, screenHeight / srcHeight);
            const float dstWidth = displayWidth * scale;
            const float dstHeight = srcHeight * scale;
            const Rectangle srcRect{0.0f, 0.0f, srcWidth, srcHeight};
            const Rectangle dstRect{
                (screenWidth - dstWidth) * 0.5f,
                (screenHeight - dstHeight) * 0.5f,
                dstWidth,
                dstHeight};
            if (presentationTexture.id)
                DrawTexturePro(presentationTexture, srcRect, dstRect, Vector2{0.0f, 0.0f}, 0.0f, WHITE);
#ifdef PS2X_GS_PARALLEL
            if (gpuFrame)
            {
                rlDrawRenderBatchActive();
                gpuFrame->ReleaseTexture();
            }
#endif
            if (m_debugUiInitialized && m_debugUiDrawCallback)
            {
                m_debugUiDrawCallback(*this, m_debugUiUserData);
            }
            EndDrawing();

            if (WindowShouldClose())
            {
                RUNTIME_LOG("[run] window close requested, breaking out of loop");
                requestStop();
                break;
            }
        }
    }
    catch (...)
    {
        presentationError = std::current_exception();
    }

    requestStop();
    if (gameThread.joinable())
    {
        gameThread.join();
    }

    if (m_debugUiInitialized && m_debugUiShutdownCallback)
    {
        m_debugUiShutdownCallback(*this, m_debugUiUserData);
        m_debugUiInitialized = false;
    }
    UnloadTexture(frameTex);
    m_gs.shutdownBackend();
    CloseWindow();

    if (presentationError)
        std::rethrow_exception(presentationError);

    RUNTIME_LOG("[run] exiting loop");
}
